import React from 'react';

import type { CSSObject } from '@emotion/react';

import type { LocalIconProps } from '../../icon';
import { StyledTextButton } from './TextButton.styles';

export type TextButtonSize = 'small' | 'medium' | 'large';

export interface TextButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  size?: TextButtonSize;
  iconPosition?: 'trailing' | 'leading';
  icon?: React.ComponentType<LocalIconProps>;
  css?: CSSObject;
}

export const TextButton = React.forwardRef<HTMLButtonElement, TextButtonProps>(
  (
    {
      size = 'medium',
      iconPosition,
      icon: IconComponent,
      children,
      css,
      type = 'button',
      ...props
    },
    forwardedRef,
  ) => (
    <StyledTextButton
      {...props}
      ref={forwardedRef}
      type={type}
      $css={css}
      $size={size}
    >
      {iconPosition === 'leading' && IconComponent && (
        <IconComponent
          size="medium"
          style={{ marginRight: '0.5rem' }}
          aria-hidden
        />
      )}
      {children}
      {iconPosition === 'trailing' && IconComponent && (
        <IconComponent
          size="medium"
          style={{ marginLeft: '0.25rem' }}
          aria-hidden
        />
      )}
    </StyledTextButton>
  ),
);

TextButton.displayName = 'TextButton';
